import { Component, useMemo, useSyncExternalStore } from 'react';
import { call, fmtDate, getCats, getEvent, getSel, getShowDetailSnapshot, getStore, iconHtml, subscribeStore } from '../api/operate.js';
import { Group, Icon } from './ui.jsx';
import { UploadBanner, QuickLinks } from './Banner.jsx';
import { TravelLegsGroup, StayGroup } from './Travel.jsx';
import VenueGroup from './Venue.jsx';
import ContactsGroup from './Contacts.jsx';
import DealGroup from './Deal.jsx';
import { DayOverview, Checklist, Notes, ContentBlock, Attachments } from './Prep.jsx';

function useShow(showId: any){
  /* Snapshot is only a change-detector. The page always reads the live show
     so photos and files stay on the real record and we don't copy it. */
  const snap = useSyncExternalStore(
    subscribeStore,
    () => getShowDetailSnapshot(showId),
    () => ''
  );
  return useMemo(() => getEvent(showId), [snap, showId]);
}

function Foot({ show }: Record<string, any>){
  return (
    <div className="show-danger-zone">
      <button type="button" className="show-danger-link" onClick={() => call('confirmDeleteEvent', show.id)}>
        Delete show
      </button>
    </div>
  );
}

class ShowPageBoundary extends Component<{ children?: any }, { error: any }> {
  constructor(props: any){
    super(props);
    this.state = { error: null };
  }
  static getDerivedStateFromError(error: any){
    return { error };
  }
  componentDidCatch(error: any){
    console.error('Show page failed', error);
  }
  render(){
    if(this.state.error){
      return (
        <div className="empty" style={{ marginTop: 28 }}>
          <b>Couldn’t open this show</b>
          <span>Something in the show details stopped the screen. You can go back. The rest of the app is still there.</span>
          <button type="button" className="btn" style={{ marginTop: 14, maxWidth: 220 }} onClick={() => call('back')}>Back</button>
        </div>
      );
    }
    return this.props.children;
  }
}

function ShowPage({ showId }: Record<string, any>){
  const show = useShow(showId);
  if(!show){
    return <div className="empty"><b>Gone</b></div>;
  }
  if(typeof window.migrateShowFlightInfo === 'function') window.migrateShowFlightInfo(show);

  const CATS = getCats() || {};
  const c = CATS[show.color || 'purple'] || CATS.purple || '#6d5efc';
  const titleColor = show.textColor && CATS[show.textColor] ? CATS[show.textColor] : '';
  const trip = show.tripId && getSel()?.trip ? getSel().trip(show.tripId) : null;
  const returnLabel = typeof window !== 'undefined' && window.__navReturn?.label;
  const backLabel = returnLabel || (trip ? trip.name : (call('overlayBackLabel') || 'Back'));

  const safeSummary = (name: any) => {
    try { return call(name, show) || ''; }
    catch(err){ console.error(name, err); return ''; }
  };
  const travelSummary = safeSummary('travelLegsGroupSummary');
  const staySummary = safeSummary('stayGroupSummary');
  const venueSummary = safeSummary('venueGroupSummary');
  const contactsSummary = safeSummary('contactsGroupSummary');
  const attachmentsSummary = safeSummary('attachmentsGroupSummary');
  const dealSummary = safeSummary('dealGroupSummary');
  const prepSummary = safeSummary('prepGroupSummary');
  return (
    <>
      <div className="detail-top">
        <div className="detail-bar">
          <button type="button" className="back-btn" onClick={() => call('back')}>
            <Icon name="chevL" size={20} /> {backLabel}
          </button>
          <div style={{ display: 'flex', gap: 8 }}>
            <button type="button" className="header-btn" style={{ width: 36, height: 36 }} onClick={() => call('shareDaySheet', show.id)}>
              <Icon name="share" size={17} />
            </button>
            <button type="button" className="header-btn" style={{ width: 36, height: 36 }} onClick={() => call('eventMenu', show.id)}>
              <Icon name="edit" size={18} />
            </button>
          </div>
        </div>
      </div>

      <div
        className={`screen-pad show-detail show-detail-react${titleColor ? ' show-title-toned' : ''}`}
        style={{ '--show-color': c, ...(titleColor ? { '--show-title': titleColor } : {}) }}
      >
        <UploadBanner showId={show.id} />

        <div className="dhero show-hero" style={{ background: `linear-gradient(155deg,${c}33,var(--card) 65%)` }}>
          <div className="cat-bar" style={{ background: c }} />
          <div className="show-hero-top">
            <span className={`tag ${show.status}`}>{show.status}</span>
            {trip ? (
              <span className="tag" style={{ background: `${c}22`, color: c }} onClick={() => call('openView', 'trip', trip.id)}>
                {trip.name}
              </span>
            ) : null}
          </div>
          <h1 className="show-hero-title">{show.eventName || show.venue || 'Untitled show'}</h1>
          {(() => {
            const bits: any[] = [];
            if(show.eventName && show.venue) bits.push(show.venue);
            const loc = [show.city, show.country].filter(Boolean).join(', ');
            if(loc) bits.push(loc);
            else if(!show.eventName && !show.venue) bits.push('City TBA');
            return bits.length ? <div className="show-hero-place">{bits.join(' · ')}</div> : null;
          })()}
          <div className="show-hero-facts">
            <span>{fmtDate ? fmtDate(show.date) : show.date}</span>
            {show.setTime ? (
              <span>Set {show.setTime}{show.endTime ? `–${show.endTime}` : ''}</span>
            ) : null}
            {show.arrival ? <span>Venue arrival {show.arrival}</span> : null}
          </div>
        </div>

        <QuickLinks show={show} />

        <DayOverview show={show} />

        <div className="show-groups">
          <Group id={`sg-${show.id}-travel`} title="Travel" icon={iconHtml('plane', 20)} summary={travelSummary}>
            <TravelLegsGroup show={show} />
          </Group>
          <Group id={`sg-${show.id}-stay`} title="Stay" icon={iconHtml('bed', 20)} summary={staySummary}>
            <StayGroup show={show} />
          </Group>
          <Group id={`sg-${show.id}-venue`} className="show-venue-panel" title="Venue & show day" icon={iconHtml('pin', 20)} summary={venueSummary}>
            <VenueGroup show={show} />
          </Group>
          <Group id={`sg-${show.id}-contacts`} title="Contacts" icon={iconHtml('users', 20)} summary={contactsSummary}>
            <ContactsGroup show={show} />
          </Group>
          <Group id={`sg-${show.id}-prep`} className="is-mid" title="Day prep" icon={iconHtml('checkList', 20)} summary={prepSummary}>
            <Checklist show={show} />
            <ContentBlock show={show} />
            <Notes show={show} />
          </Group>
          <Group id={`sg-${show.id}-attachments`} title="Attachments" icon={iconHtml('file', 20)} summary={attachmentsSummary}>
            <Attachments show={show} standalone />
          </Group>
          <Group id={`sg-${show.id}-deal`} className="is-quiet" title="Fee & deal" icon={iconHtml('coins', 20)} summary={dealSummary}>
            <DealGroup show={show} />
          </Group>
        </div>

        <div className="show-detail-foot">
          <Foot show={show} />
        </div>
      </div>
    </>
  );
}

export default function ShowPageGuarded(props: any){
  return (
    <ShowPageBoundary>
      <ShowPage {...props} />
    </ShowPageBoundary>
  );
}
